grid = [[9]*26 for _ in range(11)]
marks=[(4,10),(4,22),(5,22),(6,11),(6,13),(6,14),(6,15),(6,16),(6,17),(6,20),(6,21),(8,10),(8,19),(8,22)]
for r,c in marks:grid[r][c]=3
# Connect consecutive marker positions in each row/column
from collections import defaultdict
rows=defaultdict(list); cols=defaultdict(list)
for r,c in marks: rows[r].append(c); cols[c].append(r)
for r,cs in rows.items():
 cs=sorted(cs)
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b): grid[r][c]=2
for c,rs in cols.items():
 rs=sorted(rs)
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b): grid[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))
